SELECT clock_timestamp() AS db_at,b.id,b.product_id,b.storage_location_id,s.warehouse_id,s.code,s.deleted_at,b.container_kind,b.container_id,b.quantity,b.quantity_unpacked,b.quantity_packed,b.updated_at FROM inventory_balances b JOIN storage_locations s ON s.id=b.storage_location_id WHERE b.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND b.product_id IN (SELECT DISTINCT p.product_id FROM fbs_order_products p JOIN fbs_orders o ON o.id=p.order_id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon') ORDER BY b.product_id,b.storage_location_id,b.id LIMIT 100
